li.script:
function __sb_login(){
    var u = location.href;
    if (u.indexOf("access_token") >= 0) return false;
    if (u.indexOf("#") >=0){
        u = u.substring(0,u.indexOf("#"));
    }
    if (u.indexOf("?") < 0) {
        u = u + "?access_token=";
    }
    else {
        u = u + "&access_token=";
    }
    location.href = u;
}

